import type { Product } from '../../domain/entities/Product';
import type { CatalogueItemDto, StockLevelDto } from './ProductDtos';

export function toCatalogueItemDto(product: Product): CatalogueItemDto {
  return {
    id: product.id,
    name: product.name,
    priceCents: product.priceCents,
    available: product.available,
  };
}

export function toStockLevelDto(product: Product): StockLevelDto {
  const snapshot = product.toSnapshot();
  return {
    productId: snapshot.id,
    name: snapshot.name,
    onHand: snapshot.onHand,
    reserved: snapshot.reserved,
    available: product.available,
  };
}

